"""Compare event-context and batch-only predictors on identical retained windows.

This is a heldout diagnostic, not a public fallback or causal event-overhead
estimate. The independent matrix reference defines the eligible mask once for
both predictors. Every calibration process receives equal weight in both models.
No target durations, error thresholds, or group counts select calibration values.
Run only after both native matrices have completed.
"""

from collections import defaultdict
import hashlib
import json
import math
from pathlib import Path
import statistics
import sys

ROOT = Path('<repository>')
BASE = Path('<experiment>')
sys.path.insert(0, str(ROOT / 'tests'))
from native.finetune_event_window_matrix import _reference_windows


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False)


def read(path):
    return json.loads(Path(path).read_text())


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def digest(value):
    return hashlib.sha256(value.encode()).hexdigest()


def reference_trace(run):
    updates = {update['optimizer_step']: update for update in run['observation']['updates']}
    return [dict(row, first_batch_epoch_microstep=updates[row['optimizer_step']]['batches'][0]['epoch_microstep'])
            for row in _reference_windows(run)]


def key(row, model):
    if model == 'context':
        return row['key']
    batches = json.loads(row['key'])['batches']
    if model == 'batch_only':
        return canonical(batches)
    if model == 'batch_epoch_position':
        return canonical({'batches': batches, 'first_batch_epoch_microstep': row['first_batch_epoch_microstep']})
    raise ValueError('unknown diagnostic predictor')


def calibration_groups(runs, model):
    groups = []
    for run in runs:
        values = defaultdict(list)
        for row in reference_trace(run):
            if row['eligible']:
                values[key(row, model)].append(row['seconds'])
        groups.append(values)
    return groups


def predict(row, groups, model):
    selected = key(row, model)
    if any(len(process.get(selected, [])) < 2 for process in groups):
        raise ValueError(f'{model} predictor lacks two eligible samples in each calibration process')
    means = [statistics.mean(process[selected]) for process in groups]
    return statistics.mean(means)


def compare(rows, model):
    if not rows:
        raise ValueError('requested comparison subset is empty')
    predicted = sum(row[f'{model}_predicted_seconds'] for row in rows)
    actual = sum(row['observed_seconds'] for row in rows)
    if not math.isfinite(actual) or actual <= 0:
        raise ValueError('comparison requires positive observed time')
    return {
        'optimizer_updates': len(rows),
        'optimizer_steps': [row['optimizer_step'] for row in rows],
        'predicted_seconds': predicted,
        'observed_seconds': actual,
        'absolute_percentage_error': abs(predicted - actual) / actual * 100,
        'signed_percentage_error': (predicted - actual) / actual * 100,
    }


def paired(rows):
    context, batch, epoch = (compare(rows, model) for model in ('context', 'batch_only', 'batch_epoch_position'))
    return {
        'context': context,
        'batch_only': batch,
        'batch_epoch_position': epoch,
        'batch_epoch_position_minus_context_ape_percentage_points': epoch['absolute_percentage_error'] - context['absolute_percentage_error'],
        'batch_only_minus_context_ape_percentage_points': batch['absolute_percentage_error'] - context['absolute_percentage_error'],
    }


def run():
    result = {
        'schema_version': 'fakegpu.event_window_context_ablation.v1',
        'status': 'passed',
        'baselines': ['batch_only_ordered_descriptors_with_identical_context_eligible_mask', 'batch_descriptors_plus_first_batch_epoch_microstep_with_identical_mask'],
        'analysis_note': 'The epoch-position baseline was added after inspecting the positional association in the first ablation; its prediction means still use calibration processes only. This is exploratory diagnostic evidence, not a preregistered causal experiment.',
        'calibration_aggregation': 'equal_weight_per_process_group_mean',
        'minimum_samples_per_group_per_calibration_process': 2,
        'script_sha256': sha(__file__),
        'reference_files': {
            str(path.relative_to(ROOT)): sha(path)
            for path in (ROOT / 'tests/native/finetune_event_matrix.py', ROOT / 'tests/native/finetune_event_window_matrix.py')
        },
        'frameworks': {},
        'limitations': [
            'Both predictors use exactly the same per-process mask: global warmup and first combined batch/context occurrence excluded. This is not the default window API or an unlocked fallback for periodic events.',
            'Only calibration process timings determine predicted values. Target timings enter error calculations after the two predictors are fixed.',
            'The comparison diagnoses predictive association on this recorded workload. It does not establish a causal event overhead or a training speed improvement.',
            'Calibration subsets, actual source report signatures, schedules and event semantics were checked by the native matrix. This diagnostic does not replace its acceptance checks.',
            'All results, including worse predictions and large errors, are retained. No threshold selects results or changes a predictor.',
        ],
    }
    for framework in ('llamafactory', 'axolotl'):
        directory = BASE / 'validation' / framework
        summary_path = directory / 'event-window-summary.json'
        summary = read(summary_path)
        if summary['status'] != 'completed':
            raise ValueError(f'{framework} matrix has not completed successfully')
        matrix = read(directory / 'summary.json')
        report_paths = {role: Path(value['report']) for role, value in matrix['runs'].items()}
        reports = {role: read(path) for role, path in report_paths.items()}
        calibration = [reports[role] for role in ('calibration-1', 'calibration-2')]
        if len({run['run_identity']['uuid'] for run in reports.values()}) != len(reports):
            raise ValueError('diagnostic requires independent calibration and holdout identities')
        groups = {model: calibration_groups(calibration, model) for model in ('context', 'batch_only', 'batch_epoch_position')}
        framework_result = {
            'matrix_summary_sha256': sha(summary_path),
            'source_reports': {role: {'path': str(path), 'sha256': sha(path)} for role, path in report_paths.items()},
            'calibration': {
                role: {
                    'eligible_optimizer_steps': [row['optimizer_step'] for row in reference_trace(reports[role]) if row['eligible']],
                    'run_uuid': reports[role]['run_identity']['uuid'],
                }
                for role in ('calibration-1', 'calibration-2')
            },
            'holdouts': {},
        }
        epoch_diagnostic = {'processes': {}, 'context_groups': {},
            'interpretation': 'Periodic event distances and within-epoch position are associated in this fixture. Timing differences across these observed positions do not identify their causal source.'}
        context_positions = defaultdict(set)
        for role, run in reports.items():
            positions = defaultdict(list)
            updates = {update['optimizer_step']: update for update in run['observation']['updates']}
            for row in reference_trace(run):
                if not row['eligible']:
                    continue
                position = updates[row['optimizer_step']]['batches'][0]['epoch_microstep']
                positions[position].append(row['seconds'])
                context_positions[digest(row['key'])].add(position)
            epoch_diagnostic['processes'][role] = [
                {'first_batch_epoch_microstep': position, 'eligible_updates': len(values),
                 'mean_seconds': statistics.mean(values), 'min_seconds': min(values), 'max_seconds': max(values)}
                for position, values in sorted(positions.items())]
        epoch_diagnostic['context_groups'] = {group: sorted(positions) for group, positions in sorted(context_positions.items())}
        epoch_diagnostic['each_context_group_has_one_epoch_position'] = all(len(positions) == 1 for positions in context_positions.values())
        framework_result['epoch_position_diagnostic'] = epoch_diagnostic
        for role in ('holdout-1', 'holdout-2'):
            recorded = summary['holdout_comparisons'][role]['estimate']
            projected = {row['optimizer_step']: row for row in recorded['target_updates']}
            retained = []
            for row in reference_trace(reports[role]):
                stored = projected[row['optimizer_step']]
                if (stored['eligible'] != row['eligible'] or stored['window_id'] != digest(row['key'])
                        or stored['immediately_after_event'] != row['immediately_after_event']):
                    raise ValueError('diagnostic reference differs from recorded production eligibility/context')
                if not row['eligible']:
                    continue
                values = {model: predict(row, groups[model], model) for model in groups}
                if not math.isclose(values['context'], stored['predicted_seconds']['expected'], rel_tol=1e-12, abs_tol=1e-12):
                    raise ValueError('independent context prediction differs from production report')
                if not math.isclose(row['seconds'], stored['observed_seconds'], rel_tol=1e-12, abs_tol=1e-12):
                    raise ValueError('production target timing differs from source report')
                retained.append({
                    'optimizer_step': row['optimizer_step'],
                    'window_id': digest(row['key']),
                    'batch_group_id': digest(key(row, 'batch_only')),
                    'immediately_after_event': row['immediately_after_event'],
                    'observed_seconds': row['seconds'],
                    'context_predicted_seconds': values['context'],
                    'batch_only_predicted_seconds': values['batch_only'],
                    'batch_epoch_position_predicted_seconds': values['batch_epoch_position'],
                    'first_batch_epoch_microstep': row['first_batch_epoch_microstep'],
                })
            subsets = {
                'whole_trace': retained,
                'immediately_after_event': [row for row in retained if row['immediately_after_event']],
                'not_immediately_after_event': [row for row in retained if not row['immediately_after_event']],
                'after_72_suffix': [row for row in retained if row['optimizer_step'] > 72],
                'after_72_immediately_after_event': [row for row in retained if row['optimizer_step'] > 72 and row['immediately_after_event']],
                'after_72_not_immediately_after_event': [row for row in retained if row['optimizer_step'] > 72 and not row['immediately_after_event']],
            }
            by_context = defaultdict(list)
            for row in retained:
                by_context[row['window_id']].append(row)
            group_comparisons = [dict(window_id=group_id, **paired(rows)) for group_id, rows in sorted(by_context.items())]
            framework_result['holdouts'][role] = {
                'subsets': {name: paired(rows) for name, rows in subsets.items()},
                'context_partition_groups': group_comparisons,
                'maximum_context_partition_group_ape': {
                    model: max(group_comparisons, key=lambda entry: entry[model]['absolute_percentage_error'])
                    for model in ('context', 'batch_only', 'batch_epoch_position')
                },
                'target_updates': retained,
            }
        result['frameworks'][framework] = framework_result
    if 'torch' in sys.modules or any(name.startswith('fakegpu.') for name in sys.modules):
        raise ValueError('independent diagnostic imported production or training code')
    output = BASE / 'context-ablation.json'
    output.write_text(json.dumps(result, indent=2, sort_keys=True, allow_nan=False) + '\n')
    print(json.dumps({'status': result['status'], 'output': str(output), 'cases': len(result['frameworks']) * 2}))
    for framework, data in result['frameworks'].items():
        for role, data in data['holdouts'].items():
            print(framework, role, json.dumps({name: {model: row[model]['absolute_percentage_error'] for model in ('context', 'batch_only', 'batch_epoch_position')} for name, row in data['subsets'].items()}))


if __name__ == '__main__':
    run()

